                                  '/' + repoInfo.repo + '/check-runs' +
                                  ' -f name="' + checkName + '"' +
                                  ' -f head_sha=' + headSha +
                                  ' -f status="' + status + '"' +
                                  (conclusion ? (' -f conclusion="' + conclusion + '"') : '') +
                                  (linkBlock.detailsUrl ?
